import{_ as p,a0 as r,w as o,s as d,ao as l,I as n,x as a,a1 as e,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"如何利用 SSL/TLS 保護你的 Linux 郵件服務 | LCTT x X-CMD","titleTemplate":false,"description":"如何利用 SSL/TLS 保護你的 Linux 郵件服務 | LCTT (202005) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何利用 SSL/TLS 保護你的 Linux 郵件服務 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何利用 SSL/TLS 保護你的 Linux 郵件服務 | LCTT (202005) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202005/20200427 How to secure your Linux email services with SSL-TLS","title":"如何利用 SSL/TLS 保護你的 Linux 郵件服務","tag":"202005","desc":""},"relativePath":"202005/20200427 How to secure your Linux email services with SSL-TLS.md","filePath":"[post].md"}'),h={name:"202005/20200427 How to secure your Linux email services with SSL-TLS.md"};function c(u,s,m,k,g,S){const i=r("Link");return o(),d("div",null,[s[25]||(s[25]=l('<h1 id="如何利用-ssl-tls-保護你的-linux-郵件服務" tabindex="-1">如何利用 SSL/TLS 保護你的 Linux 郵件服務 <a class="header-anchor" href="#如何利用-ssl-tls-保護你的-linux-郵件服務" aria-label="Permalink to “如何利用 SSL/TLS 保護你的 Linux 郵件服務”">​</a></h1><blockquote><p>通過理解安全證書來保護你的 Linux 郵件服務。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202005/13/215637khaogmririavnrlk.jpg" alt=""></p><p>通常，不管你是通過<ruby>簡單郵件傳輸協議<rt>Simple Mail Transport Protocol</rt></ruby>（SMTP）或者<ruby>互聯網消息訪問協議<rt>Internet Message Access Protocol</rt></ruby>（IMAP）或<ruby>郵局協議<rt>Post Office Protocol</rt></ruby>（POP）發送或者接受郵件，郵件服務默認都是以無保護的明文來傳輸數據。近來隨着數據加密成為越來越多程序的共識，你需要<ruby>安全套接層<rt>Secure Sockets Layer</rt></ruby>/<ruby>傳輸層安全性<rt>Transport Layer Security</rt></ruby>（SSL/TLS）的安全證書來保護你的郵件服務。</p><p>首先，快速回顧一下郵件服務和協議的基本流程。郵件通過 SMTP 從 TCP 端口 25 發出。這個協議依靠 DNS <ruby>郵件交換服務器<rt>Mail eXchanger</rt></ruby>（MX）記錄的地址信息來傳輸郵件。當郵件到達郵件服務器後，可以被以下兩種服務中的任意一種檢索：使用 TCP 端口 143 的 IMAP，或者使用 TCP 端口 110 的 POP3（郵局協議第 3 版）。然而，以上服務都默認使用明文傳輸郵件和認證信息。這非常的不安全！</p>',5)),n("p",null,[s[1]||(s[1]=a("為了保護電子郵件數據和認證，這些服務都增加了一個安全功能，使它們可以利用 SSL/TLS 證書對數據流和通訊進行加密封裝。SSL/TLS 是如何加密數據的細節不在本文討論範圍，有興趣的話可以閲讀 ",-1)),e(i,{href:"https://linux.cn/article-11699-1.html"},{default:t(()=>[...s[0]||(s[0]=[a("Bryant Son 關於互聯網安全的文章",-1)])]),_:1}),s[2]||(s[2]=a("瞭解更多細節。概括的説，SSL/TLS 加密是一種基於公鑰和私鑰的算法。",-1))]),s[26]||(s[26]=l('<p>通過加入這些安全功能後，這些服務將監聽在新的 TCP 端口：</p><div class="table-wrap"><table><thead><tr><th>服務</th><th>默認 TCP 端口</th><th>SSL/TLS 端口</th></tr></thead><tbody><tr><td>SMTP</td><td>25</td><td>587</td></tr><tr><td>IMAP</td><td>143</td><td>993</td></tr><tr><td>POP3</td><td>110</td><td>995</td></tr></tbody></table></div><h3 id="生成-ssl-tls-證書" tabindex="-1">生成 SSL/TLS 證書 <a class="header-anchor" href="#生成-ssl-tls-證書" aria-label="Permalink to “生成 SSL/TLS 證書”">​</a></h3>',3)),n("p",null,[e(i,{href:"https://www.openssl.org/"},{default:t(()=>[...s[3]||(s[3]=[a("OpenSSL",-1)])]),_:1}),s[4]||(s[4]=a(" 可以生成免費的 SSL/TLS 證書，或者你也可以從公共",-1)),s[5]||(s[5]=n("ruby",null,[a("證書頒發機構"),n("rt",null,"Certificate Authoritie")],-1)),s[6]||(s[6]=a("（CA）購買。過去，生成自簽發證書十分簡單而且通用，但是由於安全被日益重視，大部分的郵件客户端是不信任自簽發證書的，除非手動設置。",-1))]),s[27]||(s[27]=l('<p>如果你只是自己使用或者做做測試，那就使用自簽發證書省點錢吧。但是如果很多人或者客户也需要使用的話，那最好還是從受信任的證書頒發機構購買。</p><p>不管是哪種情況，開始請求新證書的過程是使用 Linux 系統上的 OpenSSL 工具來創建一個<ruby>證書籤發請求<rt>Certificate Signing Request</rt></ruby>（CSR）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ openssl req -new -newkey rsa:2048 -nodes -keyout mail.mydomain.key -out mail.mydomain.csr</span></span></code></pre></div><p>這個命令會為你想保護的服務同時生成一個新的 CSR 文件和一個私匙。它會詢問你一些證書相關的問題，如：位置、服務器的<ruby>完全合規域名<rt>Fully Qualified Domain Name</rt></ruby>（FQDN）、郵件聯繫信息等等。當你輸入完這些信息後，私鑰和 CSR 文件就生成完畢了。</p><h4 id="如果你想生成自簽發證書" tabindex="-1">如果你想生成自簽發證書 <a class="header-anchor" href="#如果你想生成自簽發證書" aria-label="Permalink to “如果你想生成自簽發證書”">​</a></h4>',5)),n("p",null,[s[8]||(s[8]=a("如果你想要生成自簽發證書的話，在運行以上 CSR 命令之前，你必須先創建一個",-1)),e(i,{href:"https://en.wikipedia.org/wiki/Root_certificate"},{default:t(()=>[...s[7]||(s[7]=[a("自己的根 CA",-1)])]),_:1}),s[9]||(s[9]=a("。你可以通過以下方法創建自己的根 CA。",-1))]),s[28]||(s[28]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ openssl genrsa -des3 -out myCA.key 2048</span></span></code></pre></div><p>命令列會提示你輸入一個密碼。請輸入一個複雜點的密碼而且不要弄丟了，因為這將會是根 CA 私鑰的密碼，正如其名稱所示，它是你的證書中所有信任關係的根。</p><p>接下來，生成根 CA 證書：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ openssl req -x509 -new -nodes -key myCA.key -sha256 -days 1825 -out myCA.pem</span></span></code></pre></div><p>在回答完一些問題後，你就擁有一個有效期為 5 年的根 CA 證書了。</p><p>用之前生成的 CSR 文件，你可以請求生成一個新證書，並由您剛才創建的根 CA 簽名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ openssl x509 -req -in mail.mydomain.csr -CA myCA.pem -CAkey myCA.key -CAcreateserial -out mail.mydomain.pem -days 1825 -sha256</span></span></code></pre></div><p>輸入你的根 CA 私鑰的密碼來創建和簽署證書。</p><p>現在你有了配置電子郵件服務以增強安全性所需的兩個文件：私匙文件 <code>mail.mydomain.key</code> 和公開證書文件 <code>mail.mydomain.pem</code>。</p><h4 id="如果你願意購買證書" tabindex="-1">如果你願意購買證書 <a class="header-anchor" href="#如果你願意購買證書" aria-label="Permalink to “如果你願意購買證書”">​</a></h4><p>如果你願意從機構購買證書，則需要上傳 CSR 文件到證書頒發機構的系統中，它將會被用於生成 SSL/TLS 證書。證書可作為文件下載，比如 <code>mail.mydomain.pem</code>。很多 SSL 機構也需要你下載一箇中間證書。如果是這樣的話，你必須把這個兩個證書合併成一個，這樣電子郵件服務就可以將這兩個證書結合起來處理。可以使用以下命令把你的證書和第三方中間證書合併在一起：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat mail.mydomain.pem gd_bundle-g2-g1.crt &gt; mail.mydomain.pem</span></span></code></pre></div><p>值得一提的是 <code>.pem</code> 文件後綴代表<ruby>隱私增強郵件<rt>Privacy-Enhanced Mail</rt></ruby>。</p><p>現在你就有全部的設置郵件服務安全所需文件了：私匙文件 <code>mail.mydomain.key</code> 和組合的公開證書文件 <code>mail.mydomain.pem</code>。</p><h3 id="為你的文件生成一個安全的文件夾" tabindex="-1">為你的文件生成一個安全的文件夾 <a class="header-anchor" href="#為你的文件生成一個安全的文件夾" aria-label="Permalink to “為你的文件生成一個安全的文件夾”">​</a></h3><p>不管你是的證書是自簽發的或者從機構購買，你都需要生成一個安全的，管理員擁有的文件夾用於保存這兩個文件。可以使用以下命令來生成：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir /etc/pki/tls</span></span>
<span class="line"><span>$ chown root:root /etc/pki/tls</span></span>
<span class="line"><span>$ chmod 700 /etc/pki/tls</span></span></code></pre></div><p>在複製文件到 <code>/etc/pki/tls</code> 後，再次設置這些文件的權限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod 600 /etc/pki/tls/*</span></span></code></pre></div><h3 id="配置你的-smtp-和-imap-服務" tabindex="-1">配置你的 SMTP 和 IMAP 服務 <a class="header-anchor" href="#配置你的-smtp-和-imap-服務" aria-label="Permalink to “配置你的 SMTP 和 IMAP 服務”">​</a></h3><p>接下來，讓 SMTP 和 IMAP 服務使用新的安全證書。我們用 <code>postfix</code> 和 <code>dovecot</code> 來作為例子。</p><p>用你順手的編輯器來編輯 <code>/etc/postfix/main.cf</code> 文件。添加以下幾行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>smtpd_use_tls = yes</span></span>
<span class="line"><span>smtpd_tls_cert_file = /etc/pki/tls/mail.mydomain.pem</span></span>
<span class="line"><span>smtpd_tls_key_file = /etc/pki/tls/mail.mydomain.key</span></span></code></pre></div><h3 id="自定義選項" tabindex="-1">自定義選項 <a class="header-anchor" href="#自定義選項" aria-label="Permalink to “自定義選項”">​</a></h3><p>以下選項可以啓用或禁用各種加密算法，協議等等：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>smtpd_tls_eecdh_grade = strong</span></span>
<span class="line"><span>smtpd_tls_protocols= !SSLv2, !SSLv3, !TLSv1, !TLSv1.1</span></span>
<span class="line"><span>smtpd_tls_mandatory_protocols= !SSLv2, !SSLv3, !TLSv1, !TLSv1.1</span></span>
<span class="line"><span>smtpd_tls_mandatory_ciphers = high</span></span>
<span class="line"><span>smtpd_tls_security_level=may</span></span>
<span class="line"><span>smtpd_tls_ciphers = high</span></span>
<span class="line"><span>tls_preempt_cipherlist = yes</span></span>
<span class="line"><span>smtpd_tls_mandatory_exclude_ciphers = aNULL, MD5 , DES, ADH, RC4, PSD, SRP, 3DES, eNULL</span></span>
<span class="line"><span>smtpd_tls_exclude_ciphers = aNULL, MD5 , DES, ADH, RC4, PSD, SRP, 3DES, eNULL</span></span>
<span class="line"><span>smtp_tls_mandatory_protocols = !SSLv2, !SSLv3, !TLSv1, !TLSv1.1</span></span>
<span class="line"><span>smtp_tls_protocols = !SSLv2, !SSLv3, !TLSv1, !TLSv1.1</span></span></code></pre></div><p>編輯 <code>/etc/dovecot/dovecot.conf</code> 文件，添加以下三行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ssl = required</span></span>
<span class="line"><span>ssl_cert = &amp;lt;/etc/pki/tls/mail.mydomain.pem</span></span>
<span class="line"><span>ssl_key = &amp;lt;/etc/pki/tls/mail.mydomain.key</span></span></code></pre></div><p>添加下列更多選項來啓用或禁用各種加密算法、協議等等（我把這些留給你來理解）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ssl_cipher_list = EECDH+ECDSA+AESGCM:EECDH+aRSA+AESGCM:EECDH+ECDSA+SHA384:EECDH+ECDSA+SHA256:EECDH+aRSA+SHA384:EECDH+aRSA+SHA256:EECDH+aRSA+RC4:EECDH:EDH+aRSA:ALL:!aNULL:!eNULL:!LOW:!3DES:!MD5:!EXP:!PSK:!SRP:!DSS:!RC4:!SSLv2</span></span>
<span class="line"><span>ssl_prefer_server_ciphers = yes</span></span>
<span class="line"><span>ssl_protocols = !SSLv2 !SSLv3 !TLSv1 !TLSv1.1</span></span>
<span class="line"><span>ssl_min_protocol = TLSv1.2</span></span></code></pre></div><h3 id="設置-selinux-上下文" tabindex="-1">設置 SELinux 上下文 <a class="header-anchor" href="#設置-selinux-上下文" aria-label="Permalink to “設置 SELinux 上下文”">​</a></h3><p>如果你的 Linux 發行版啓用了 SELinux，請為你的新證書文件設置正確的 SELinux 上下文。</p><p>對於 Postfix 設置 SELinux：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chcon -u system_u -t cert_t mail.mydomain.*</span></span></code></pre></div><p>對於 Dovecot 設置 SELinux：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chcon -u system_u -t dovecot_cert_t mail.mydomain.*</span></span></code></pre></div><p>重啓這些服務，並與你相應更新過的電子郵件客户端配置連接。有些電子郵件客户端會自動探測到新的端口，有些則需要你手動更新。</p><h3 id="測試配置" tabindex="-1">測試配置 <a class="header-anchor" href="#測試配置" aria-label="Permalink to “測試配置”">​</a></h3><p>用 <code>openssl</code> 命令列和 <code>s_client</code> 插件來簡單測試一下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ openssl s_client -connect mail.mydomain.com:993</span></span>
<span class="line"><span>$ openssl s_client -starttls imap -connect mail.mydomain.com:143</span></span>
<span class="line"><span>$ openssl s_client -starttls smtp -connect mail.mydomain.com:587</span></span></code></pre></div><p>這些測試命令會打印出很多信息，關於你使用的連接、證書、加密算法、會話和協議。這不僅是一個驗證新設置的好方法，也可以確認你使用了適當的證書，以及在 postfix 或 dovecot 配置文件中定義的安全設置正確。</p><p>保持安全！</p><hr>`,43)),n("p",null,[s[11]||(s[11]=a("via: ",-1)),e(i,{href:"https://opensource.com/article/20/4/securing-linux-email"},{default:t(()=>[...s[10]||(s[10]=[a("https://opensource.com/article/20/4/securing-linux-email",-1)])]),_:1})]),n("p",null,[s[16]||(s[16]=a("作者：",-1)),e(i,{href:"https://opensource.com/users/marc-skinner"},{default:t(()=>[...s[12]||(s[12]=[a("Marc Skinner",-1)])]),_:1}),s[17]||(s[17]=a(" 選題：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[13]||(s[13]=[a("lujun9972",-1)])]),_:1}),s[18]||(s[18]=a(" 譯者：",-1)),e(i,{href:"https://github.com/Acceleratorrrr"},{default:t(()=>[...s[14]||(s[14]=[a("Acceleratorrrr",-1)])]),_:1}),s[19]||(s[19]=a(" 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:t(()=>[...s[15]||(s[15]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[22]||(s[22]=a("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[20]||(s[20]=[a("LCTT",-1)])]),_:1}),s[23]||(s[23]=a(" 原創編譯，",-1)),e(i,{href:"https://linux.cn/"},{default:t(()=>[...s[21]||(s[21]=[a("Linux中國",-1)])]),_:1}),s[24]||(s[24]=a(" 榮譽推出",-1))])])}const C=p(h,[["render",c]]);export{L as __pageData,C as default};
